const MARKER = "PNO_APPROVED_MODAL_V18";

const RUNTIME = "\n// PNO_APPROVED_MODAL_V18: approved DEV-only warehouse parcel modal.\n// UI-only: no timer, no SQL persistence, no realtime/upstream background polling.\nconst PNO_V18_BROWSER_CACHE_MS = 60 * 1000;\nconst pnoV18BrowserCache = new Map();\nconst pnoV18State = {\n  proofId: \"\",\n  day: \"\",\n  routeName: \"\",\n  type: \"total\",\n  page: 1,\n  total: 0,\n  rows: [],\n  expandedBag: \"\",\n  bagRows: null,\n  busy: false,\n};\n\nfunction pnoV18Key(type, page) {\n  return [state.branch, pnoV18State.proofId, pnoV18State.day, type, page].join(\"|\");\n}\n\nfunction pnoV18Number(value) {\n  const number = Number(value);\n  return Number.isFinite(number) ? number : null;\n}\n\nfunction pnoV18SourceRow() {\n  const proof = String(pnoV18State.proofId || \"\").trim().toUpperCase();\n  const pools = [state.currentRows || [], state.rows || [], state.archiveRows || []];\n  for (const pool of pools) {\n    const row = pool.find((item) => String(item?.proofId || \"\").trim().toUpperCase() === proof);\n    if (row) return row;\n  }\n  return null;\n}\n\nfunction pnoV18EnsureUi() {\n  const dialog = el(\"pending-parcels-dialog\");\n  if (!dialog) return;\n  const card = dialog.querySelector(\".parcel-list-card\");\n  if (!card || card.dataset.pnoV18 === \"1\") return;\n  card.dataset.pnoV18 = \"1\";\n  card.innerHTML =\n    '<button id=\"pending-parcels-close\" class=\"dialog-close\" type=\"button\" aria-label=\"ปิด\">×</button>' +\n    '<div class=\"pno-v18-head\"><div><h2>รายการพัสดุเข้าคลัง</h2><p id=\"pending-parcels-trip\" class=\"muted\"></p></div></div>' +\n    '<div id=\"pno-v18-summary\" class=\"pno-v18-summary\"></div>' +\n    '<div class=\"pno-v18-toolbar\">' +\n      '<div id=\"pno-v18-tabs\" class=\"pno-v18-tabs\">' +\n        '<button type=\"button\" data-pno-v18-type=\"total\">ทั้งหมด</button>' +\n        '<button type=\"button\" data-pno-v18-type=\"already\">เข้าคลังแล้ว</button>' +\n        '<button type=\"button\" data-pno-v18-type=\"no_entry\">คงเหลือ</button>' +\n        '<button type=\"button\" data-pno-v18-type=\"bag\">แบ็กกิ้ง</button>' +\n      '</div>' +\n      '<div class=\"pno-v18-actions\">' +\n        '<button id=\"copy-pending-parcels\" class=\"btn btn-secondary\" type=\"button\">คัดลอก</button>' +\n        '<button id=\"export-pending-parcels\" class=\"btn btn-primary\" type=\"button\">Export</button>' +\n      '</div>' +\n    '</div>' +\n    '<div id=\"pending-parcels-loading\" class=\"empty-state\">กำลังโหลดรายการ…</div>' +\n    '<div id=\"pending-parcels-list\" class=\"pno-v18-list hidden\"></div>' +\n    '<div id=\"pno-v18-pager\" class=\"pno-v18-pager hidden\">' +\n      '<button id=\"pno-v18-prev\" class=\"btn btn-secondary\" type=\"button\">← ก่อนหน้า</button>' +\n      '<span id=\"pno-v18-page\">หน้า 1</span>' +\n      '<button id=\"pno-v18-next\" class=\"btn btn-secondary\" type=\"button\">ถัดไป →</button>' +\n    '</div>';\n\n  el(\"pending-parcels-close\").onclick = () => dialog.close();\n  el(\"copy-pending-parcels\").onclick = pnoV18Copy;\n  el(\"export-pending-parcels\").onclick = pnoV18Export;\n  dialog.querySelectorAll(\"[data-pno-v18-type]\").forEach((button) => {\n    button.onclick = () => {\n      const type = button.dataset.pnoV18Type;\n      if (type === \"bag\") void pnoV18LoadBags();\n      else void pnoV18Load(type, 1);\n    };\n  });\n  el(\"pno-v18-prev\").onclick = () => void pnoV18Load(pnoV18State.type, Math.max(1, pnoV18State.page - 1));\n  el(\"pno-v18-next\").onclick = () => void pnoV18Load(pnoV18State.type, pnoV18State.page + 1);\n\n  if (!document.getElementById(\"pno-approved-modal-v18-style\")) {\n    const style = document.createElement(\"style\");\n    style.id = \"pno-approved-modal-v18-style\";\n    style.textContent = [\n      \".ms-page #pending-parcels-dialog{width:min(1120px,calc(100vw - 24px));max-width:1120px}\",\n      \".ms-page #pending-parcels-dialog .parcel-list-card{width:100%;max-width:none;border:1px solid #d8dbd6;border-top:4px solid #ffd400;border-radius:9px;background:#fff;box-shadow:0 8px 28px rgba(21,21,21,.16);overflow:hidden}\",\n      \".ms-page .pno-v18-head{padding:15px 18px 13px;border-bottom:1px solid #d8dbd6;background:#fff}\",\n      \".ms-page .pno-v18-head h2{margin:0;color:#151515;font-size:18px;font-weight:900}\",\n      \".ms-page .pno-v18-head .muted{margin:4px 0 0;color:#62676d;font-size:12px}\",\n      \".ms-page .pno-v18-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));background:#fafaf8;border-bottom:1px solid #d8dbd6}\",\n      \".ms-page .pno-v18-summary-item{min-height:70px;padding:13px 18px;display:flex;align-items:center;justify-content:space-between;gap:12px}\",\n      \".ms-page .pno-v18-summary-item+.pno-v18-summary-item{border-left:1px solid #d8dbd6}\",\n      \".ms-page .pno-v18-summary-label{color:#505650;font-size:12px;font-weight:800}\",\n      \".ms-page .pno-v18-summary-note{margin-top:2px;color:#777d78;font-size:10.5px}\",\n      \".ms-page .pno-v18-summary-value{color:#151515;font-size:34px;line-height:1;font-weight:900;font-variant-numeric:tabular-nums}\",\n      \".ms-page .pno-v18-toolbar{padding:10px 16px;display:flex;align-items:center;gap:10px;border-bottom:1px solid #d8dbd6;background:#fff}\",\n      \".ms-page .pno-v18-tabs{display:flex;flex-wrap:wrap;gap:6px}\",\n      \".ms-page .pno-v18-tabs button{min-height:34px;padding:7px 11px;border:1px solid #c8cac6;border-radius:6px;background:#fff;color:#202124;font-size:12px;font-weight:800;cursor:pointer}\",\n      \".ms-page .pno-v18-tabs button.is-active{background:#ffd400;border-color:#b48f00;color:#111}\",\n      \".ms-page .pno-v18-actions{margin-left:auto;display:flex;gap:6px}\",\n      \".ms-page .pno-v18-list{overflow:auto}\",\n      \".ms-page .pno-v18-table{width:100%;min-width:820px;border-collapse:collapse}\",\n      \".ms-page .pno-v18-table th{padding:10px 12px;background:#f0f2ef;border-bottom:1px solid #d8dbd6;color:#505650;text-align:left;font-size:11px;font-weight:900;white-space:nowrap}\",\n      \".ms-page .pno-v18-table td{padding:11px 12px;border-bottom:1px solid #eceeea;color:#252525;font-size:12px;vertical-align:middle}\",\n      \".ms-page .pno-v18-table tr:hover>td{background:#fffdf3}\",\n      \".ms-page .pno-v18-pno{color:#151515;font-weight:900;font-variant-numeric:tabular-nums}\",\n      \".ms-page .pno-v18-badge{display:inline-flex;align-items:center;min-height:25px;padding:4px 10px;border-radius:999px;border:1px solid #a07a00;background:#ffd400;color:#111;font-size:10.5px;font-weight:900;white-space:nowrap}\",\n      \".ms-page .pno-v18-badge.is-dark{border-color:#151515;background:#2b2b2b;color:#fff}\",\n      \".ms-page .pno-v18-badge.is-backing{border-color:#5F70DB;background:#7B8CFF;color:#fff}\",\n      \".ms-page .pno-v18-badge.is-gray{border-color:#5f666b;background:#c8cbc7;color:#111}\",\n      \".ms-page .pno-v18-bag-meta{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\",\n      \".ms-page .pno-v18-bag-link{padding:0;border:0;background:transparent;color:#151515;font-weight:900;text-decoration:underline;text-decoration-color:#d2b000;text-underline-offset:3px;cursor:pointer}\",\n      \".ms-page .pno-v18-count{display:inline-flex;min-width:58px;justify-content:center;padding:5px 9px;border:1px solid #c8cac6;border-radius:6px;background:#fff;color:#151515;font-weight:900}\",\n      \".ms-page .pno-v18-expand td{padding:0!important;background:#fafaf8!important}\",\n      \".ms-page .pno-v18-expand-box{padding:12px 16px 14px;border-top:1px solid #eceeea;background:#fafaf8}\",\n      \".ms-page .pno-v18-inner{width:100%;min-width:640px;border-collapse:collapse;border:1px solid #d8dbd6;background:#fff}\",\n      \".ms-page .pno-v18-inner th{padding:9px 11px;background:#f7f8f6;color:#505650;font-size:10.5px;text-align:left}\",\n      \".ms-page .pno-v18-inner td{padding:10px 11px;border-bottom:1px solid #eceeea;font-size:11.5px}\",\n      \".ms-page .pno-v18-pager{padding:10px 16px;display:flex;align-items:center;justify-content:flex-end;gap:9px;border-top:1px solid #d8dbd6;background:#fafaf8}\",\n      \".ms-page .pno-v18-pager>span{color:#62676d;font-size:11px}\",\n      \".ms-page .pno-v18-source-note{padding:10px 16px;color:#62676d;font-size:11px}\",\n      \"@media(max-width:720px){.ms-page #pending-parcels-dialog{width:calc(100vw - 12px)}.ms-page .pno-v18-summary{grid-template-columns:1fr}.ms-page .pno-v18-summary-item+.pno-v18-summary-item{border-left:0;border-top:1px solid #d8dbd6}.ms-page .pno-v18-summary-item{min-height:58px;padding:10px 13px}.ms-page .pno-v18-summary-value{font-size:28px}.ms-page .pno-v18-toolbar{align-items:stretch;flex-direction:column}.ms-page .pno-v18-actions{width:100%;margin-left:0}.ms-page .pno-v18-actions .btn{flex:1}.ms-page .pno-v18-pager{justify-content:space-between}}\"\n    ].join(\"\\\\n\");\n    document.head.append(style);\n  }\n}\n\nfunction pnoV18RenderSummary() {\n  const row = pnoV18SourceRow();\n  const total = pnoV18Number(row?.expectedParcels);\n  const entered = pnoV18Number(row?.enteredParcels);\n  const pending = pnoV18Number(row?.pendingParcels);\n  const values = [\n    [\"ทั้งหมด\", \"รายการพัสดุ\", total ?? (pnoV18State.type === \"total\" ? pnoV18State.total : null)],\n    [\"เข้าคลังแล้ว\", \"สแกนเข้าแล้ว\", entered],\n    [\"คงเหลือ\", \"ยังไม่เข้าคลัง\", pending],\n  ];\n  el(\"pno-v18-summary\").innerHTML = values.map((item) =>\n    '<div class=\"pno-v18-summary-item\"><div><div class=\"pno-v18-summary-label\">' + item[0] +\n    '</div><div class=\"pno-v18-summary-note\">' + item[1] +\n    '</div></div><div class=\"pno-v18-summary-value\">' + (item[2] === null ? \"-\" : nf.format(item[2])) + '</div></div>'\n  ).join(\"\");\n}\n\nfunction pnoV18SetActive(type) {\n  el(\"pending-parcels-dialog\").querySelectorAll(\"[data-pno-v18-type]\").forEach((button) => {\n    button.classList.toggle(\"is-active\", button.dataset.pnoV18Type === type);\n  });\n}\n\nasync function pnoV18Fetch(type, page) {\n  const key = pnoV18Key(type, page);\n  const cached = pnoV18BrowserCache.get(key);\n  if (cached && cached.until > Date.now()) return cached.value;\n  const value = await apiGet(\"pendingParcels\", {\n    branch: state.branch,\n    proofId: pnoV18State.proofId,\n    day: pnoV18State.day,\n    type,\n    page,\n  });\n  pnoV18BrowserCache.set(key, { until: Date.now() + PNO_V18_BROWSER_CACHE_MS, value });\n  return value;\n}\n\nfunction pnoV18ActionClass(action) {\n  const value = String(action || \"\").toLowerCase();\n  if (value.includes(\"แบ็ก\") || value.includes(\"back\") || value.includes(\"bag\")) return \"is-backing\";\n  if (value.includes(\"ออกคลัง\") || value.includes(\"ออก\")) return \"is-dark\";\n  if (!value || value === \"-\") return \"is-gray\";\n  return \"\";\n}\n\nfunction pnoV18StatusClass(type, status) {\n  if (type === \"no_entry\" || /คงเหลือ|ยังไม่เข้า/i.test(String(status || \"\"))) return \"is-dark\";\n  return \"\";\n}\n\nfunction pnoV18TypeLabel(type) {\n  return type === \"already\" ? \"เข้าคลังแล้ว\" : type === \"no_entry\" ? \"คงเหลือ\" : \"ทั้งหมด\";\n}\n\nfunction pnoV18RenderRows(type, rows) {\n  const list = el(\"pending-parcels-list\");\n  if (!rows.length) {\n    list.innerHTML = '<div class=\"empty-state\">ไม่พบรายการพัสดุ</div>';\n    return;\n  }\n  list.innerHTML =\n    '<table class=\"pno-v18-table\"><thead><tr><th>#</th><th>PNO</th><th>สถานะ</th><th>ล่าสุด</th><th>ปลายทาง</th><th>เวลา</th></tr></thead><tbody>' +\n    rows.map((item, index) => {\n      const status = item.status || pnoV18TypeLabel(type);\n      const target = [item.targetHub, item.targetBranch].filter(Boolean).join(\" · \") || \"-\";\n      return '<tr><td>' + nf.format((pnoV18State.page - 1) * 200 + index + 1) +\n        '</td><td class=\"pno-v18-pno\">' + esc(item.pno || \"-\") +\n        '</td><td><span class=\"pno-v18-badge ' + pnoV18StatusClass(type, status) + '\">' + esc(status) +\n        '</span></td><td><span class=\"pno-v18-badge ' + pnoV18ActionClass(item.lastAction) + '\">' + esc(item.lastAction || \"-\") +\n        '</span></td><td>' + esc(target) +\n        '</td><td>' + esc(item.lastActionAt || \"-\") + '</td></tr>';\n    }).join(\"\") + '</tbody></table>';\n}\n\nasync function pnoV18Load(type, page) {\n  if (pnoV18State.busy) return;\n  pnoV18State.busy = true;\n  pnoV18State.type = type;\n  pnoV18State.page = Math.max(1, Number(page) || 1);\n  pnoV18State.expandedBag = \"\";\n  pnoV18SetActive(type);\n  el(\"pending-parcels-loading\").textContent = \"กำลังโหลดรายการ…\";\n  el(\"pending-parcels-loading\").classList.remove(\"hidden\");\n  el(\"pending-parcels-list\").classList.add(\"hidden\");\n  el(\"pno-v18-pager\").classList.add(\"hidden\");\n  try {\n    const result = await pnoV18Fetch(type, pnoV18State.page);\n    pnoV18State.rows = Array.isArray(result.parcels) ? result.parcels : [];\n    pnoV18State.total = Number(result.total || pnoV18State.rows.length) || 0;\n    pnoV18State.routeName = result.routeName || pnoV18State.routeName || \"\";\n    pendingParcelRows = pnoV18State.rows;\n    el(\"pending-parcels-trip\").textContent = [result.proofId || pnoV18State.proofId, pnoV18State.routeName].filter(Boolean).join(\" · \");\n    pnoV18RenderSummary();\n    pnoV18RenderRows(type, pnoV18State.rows);\n    const pages = Math.max(1, Math.ceil(pnoV18State.total / 200));\n    el(\"pno-v18-page\").textContent = \"หน้า \" + nf.format(pnoV18State.page) + \" / \" + nf.format(pages);\n    el(\"pno-v18-prev\").disabled = pnoV18State.page <= 1;\n    el(\"pno-v18-next\").disabled = pnoV18State.page >= pages;\n    el(\"pending-parcels-loading\").classList.add(\"hidden\");\n    el(\"pending-parcels-list\").classList.remove(\"hidden\");\n    el(\"pno-v18-pager\").classList.remove(\"hidden\");\n  } catch (error) {\n    el(\"pending-parcels-loading\").innerHTML = '<strong>' + esc(error.message) + '</strong><span>ตรวจสอบเซสชันพัสดุเข้าคลังแล้วลองใหม่</span>';\n  } finally {\n    pnoV18State.busy = false;\n  }\n}\n\nfunction pnoV18BagGroups(rows) {\n  const groups = new Map();\n  rows.forEach((item) => {\n    const bag = String(item.backingNo || \"\").trim();\n    if (!bag) return;\n    if (!groups.has(bag)) groups.set(bag, []);\n    groups.get(bag).push(item);\n  });\n  return [...groups.entries()].sort((a, b) => a[0].localeCompare(b[0]));\n}\n\nfunction pnoV18RenderBags(rows) {\n  const groups = pnoV18BagGroups(rows);\n  const list = el(\"pending-parcels-list\");\n  if (!groups.length) {\n    list.innerHTML = '<div class=\"empty-state\">ไม่พบเลขถุงแบ็กกิ้ง</div>';\n    return;\n  }\n  let html = '<table class=\"pno-v18-table\"><thead><tr><th>#</th><th>เลขถุงแบ็กกิ้ง</th><th>จำนวนพัสดุ</th><th></th></tr></thead><tbody>';\n  groups.forEach(([bag, items], index) => {\n    const open = pnoV18State.expandedBag === bag;\n    html += '<tr><td>' + nf.format(index + 1) +\n      '</td><td><div class=\"pno-v18-bag-meta\"><button class=\"pno-v18-bag-link\" type=\"button\" data-pno-v18-bag=\"' + esc(bag) + '\">' + esc(bag) +\n      '</button><span class=\"pno-v18-badge\">เข้าคลังแล้ว</span></div></td>' +\n      '<td><span class=\"pno-v18-count\">' + nf.format(items.length) + ' ชิ้น</span></td>' +\n      '<td><button class=\"btn btn-secondary\" type=\"button\" data-pno-v18-bag=\"' + esc(bag) + '\">' + (open ? \"ซ่อนรายการ ▴\" : \"ดูรายการ ▾\") + '</button></td></tr>';\n    if (open) {\n      html += '<tr class=\"pno-v18-expand\"><td colspan=\"4\"><div class=\"pno-v18-expand-box\">' +\n        '<table class=\"pno-v18-inner\"><thead><tr><th>#</th><th>PNO</th><th>ล่าสุด</th><th>เวลา</th></tr></thead><tbody>' +\n        items.map((item, itemIndex) =>\n          '<tr><td>' + nf.format(itemIndex + 1) +\n          '</td><td class=\"pno-v18-pno\">' + esc(item.pno || \"-\") +\n          '</td><td><span class=\"pno-v18-badge is-backing\">' + esc(item.lastAction || \"แบ็กกิ้ง\") +\n          '</span></td><td>' + esc(item.lastActionAt || \"-\") + '</td></tr>'\n        ).join(\"\") + '</tbody></table></div></td></tr>';\n    }\n  });\n  html += '</tbody></table>';\n  list.innerHTML = html;\n  list.querySelectorAll(\"[data-pno-v18-bag]\").forEach((button) => {\n    button.onclick = () => {\n      const bag = button.dataset.pnoV18Bag;\n      pnoV18State.expandedBag = pnoV18State.expandedBag === bag ? \"\" : bag;\n      pnoV18RenderBags(rows);\n    };\n  });\n}\n\nasync function pnoV18LoadBags() {\n  if (pnoV18State.busy) return;\n  pnoV18State.busy = true;\n  pnoV18State.type = \"bag\";\n  pnoV18State.expandedBag = \"\";\n  pnoV18SetActive(\"bag\");\n  el(\"pending-parcels-loading\").textContent = \"กำลังรวมเลขถุงแบ็กกิ้ง…\";\n  el(\"pending-parcels-loading\").classList.remove(\"hidden\");\n  el(\"pending-parcels-list\").classList.add(\"hidden\");\n  el(\"pno-v18-pager\").classList.add(\"hidden\");\n  try {\n    const first = await pnoV18Fetch(\"total\", 1);\n    const total = Number(first.total || (first.parcels || []).length) || 0;\n    const pages = Math.max(1, Math.ceil(total / 200));\n    const all = [...(first.parcels || [])];\n    for (let page = 2; page <= pages; page += 1) {\n      el(\"pending-parcels-loading\").textContent = \"กำลังรวมเลขถุงแบ็กกิ้ง… \" + nf.format(page) + \"/\" + nf.format(pages);\n      const result = await pnoV18Fetch(\"total\", page);\n      all.push(...(result.parcels || []));\n    }\n    pnoV18State.bagRows = all;\n    pnoV18State.total = total;\n    pendingParcelRows = all;\n    pnoV18RenderSummary();\n    pnoV18RenderBags(all);\n    el(\"pending-parcels-loading\").classList.add(\"hidden\");\n    el(\"pending-parcels-list\").classList.remove(\"hidden\");\n  } catch (error) {\n    el(\"pending-parcels-loading\").innerHTML = '<strong>' + esc(error.message) + '</strong><span>ตรวจสอบเซสชันพัสดุเข้าคลังแล้วลองใหม่</span>';\n  } finally {\n    pnoV18State.busy = false;\n  }\n}\n\nasync function pnoV18Copy() {\n  const rows = pnoV18State.type === \"bag\" ? (pnoV18State.bagRows || []) : pnoV18State.rows;\n  if (!rows.length) return toast(\"ยังไม่มีเลขพัสดุให้คัดลอก\", true);\n  await navigator.clipboard.writeText(rows.map((row) => row.pno || \"\").filter(Boolean).join(\"\\\\n\"));\n  toast(\"คัดลอกเลขพัสดุ \" + nf.format(rows.length) + \" รายการแล้ว\");\n}\n\nfunction pnoV18Export() {\n  const rows = pnoV18State.type === \"bag\" ? (pnoV18State.bagRows || []) : pnoV18State.rows;\n  if (!rows.length) return toast(\"ยังไม่มีข้อมูลสำหรับ Export\", true);\n  const values = rows.map((row, index) => ({\n    \"ลำดับ\": index + 1,\n    \"PNO\": row.pno || \"\",\n    \"เลขถุงแบ็กกิ้ง\": row.backingNo || \"\",\n    \"สถานะ\": row.status || pnoV18TypeLabel(pnoV18State.type),\n    \"การดำเนินการล่าสุด\": row.lastAction || \"\",\n    \"เวลา\": row.lastActionAt || \"\",\n    \"HUB ปลายทาง\": row.targetHub || \"\",\n    \"สาขาปลายทาง\": row.targetBranch || \"\",\n  }));\n  const ws = XLSX.utils.json_to_sheet(values);\n  const wb = XLSX.utils.book_new();\n  XLSX.utils.book_append_sheet(wb, ws, \"รายการพัสดุ\");\n  XLSX.writeFile(wb, \"รายการพัสดุเข้าคลัง_\" + new Date().toISOString().slice(0,10) + \".xlsx\");\n}\n\nasync function openPendingParcels(proofId, day) {\n  pnoV18EnsureUi();\n  pnoV18State.proofId = String(proofId || \"\").trim();\n  pnoV18State.day = String(day || \"\").trim();\n  pnoV18State.routeName = \"\";\n  pnoV18State.type = \"total\";\n  pnoV18State.page = 1;\n  pnoV18State.total = 0;\n  pnoV18State.rows = [];\n  pnoV18State.bagRows = null;\n  pnoV18State.expandedBag = \"\";\n  el(\"pending-parcels-trip\").textContent = pnoV18State.proofId;\n  pnoV18RenderSummary();\n  el(\"pending-parcels-dialog\").showModal();\n  await pnoV18Load(\"total\", 1);\n}\n\ndocument.addEventListener(\"DOMContentLoaded\", pnoV18EnsureUi);\n";

export function patchPnoApprovedModalV18(source) {
  const output = String(source || "");
  if (output.includes(MARKER)) return output;
  if (!output.includes("PNO_ROUND2_UI_V2"))
    throw new Error(MARKER + ": Round2 frontend prerequisite missing");
  return output + "\n\n" + RUNTIME + "\n";
}
